import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  lines.push(invoice.number ?? 'DRAFT');
  lines.push(invoice.customerId);

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const unitPriceFormatted = formatEuros(line.unitPrice);
    const totalFormatted = formatEuros(total);
    let lineText = `${line.qty} × ${line.name} @ ${unitPriceFormatted} = ${totalFormatted}`;
    if (line.discountPercent) {
      const discount = lineDiscount(line);
      lineText += ` (${line.discountPercent}% off, -${formatEuros(discount)})`;
    }
    lines.push(lineText);
  }

  const totals = invoiceTotals(invoice);
  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return lines.join('\n');
}

