import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice creates an invoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Printed flyer A4 (each)');
});

test('createInvoice reports unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice rejects invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '10/07/2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects non-existent date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects missing date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects non-integer quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 3.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const originalLines = JSON.stringify(lines);
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.equal(JSON.stringify(lines), originalLines);
});

test('createInvoice returns a copy of lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  r.value.lines[0].qty = 999;
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r2.value.lines[0].qty, 5);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal handles quantity of 1', () => {
  const line = { qty: 1, unitPrice: 1500 };
  assert.equal(lineTotal(line), 1500);
});

test('invoiceTotals calculates subtotal from single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals calculates subtotal from multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 5 * 8500 + 3 * 9500);
  assert.equal(totals.total, 5 * 8500 + 3 * 9500);
});

test('invoiceTotals returns subtotal and total as equal for now', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'ICON-SET', qty: 50 },
    ],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, totals.total);
});

test('addLine adds a new line to the invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 3);
});

test('addLine increases qty for existing SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 8);
});

test('addLine does not mutate the original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const originalLength = r1.value.lines.length;
  addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r1.value.lines.length, originalLength);
});

test('addLine rejects invalid quantity', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(r1.value, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects unknown SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(r1.value, { sku: 'UNKNOWN-SKU', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine rejects non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine removes a line from the invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const r2 = removeLine(r1.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine does not mutate the original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const originalLength = r1.value.lines.length;
  removeLine(r1.value, 'DES-HOUR');
  assert.equal(r1.value.lines.length, originalLength);
});

test('removeLine reports line not found', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(r1.value, 'UNKNOWN-SKU'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine rejects removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(removeLine(r1.value, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine rejects non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21 },
    ],
  };
  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice assigns number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r.value, []);
